def solve(rows):
    state = 6
    kept_rows = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 11 != 2 or i == len(rows) - 1:
            kept_rows.append(row)
        state = 0 if weight == 0 else (5 * state + weight) % 11

    if not kept_rows:
        return []

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length
    rotated_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    expiry_days = []
    for row in rotated_rows:
        if isinstance(row, list) and len(row) == 2:
            day = row[0]
            lifetime = row[1]
            expiry_day = day + lifetime
            while expiry_day % 7 in (5, 6):
                expiry_day += 1
            expiry_days.append(expiry_day)

    return expiry_days

